// ----------------------------------------------------
// Indonesian Terbilang Logic
// ----------------------------------------------------
function angkaKeTerbilang(nominal) {
  const units = ["", "Satu", "Dua", "Tiga", "Empat", "Lima", "Enam", "Tujuh", "Delapan", "Sembilan", "Sepuluh", "Sebelas"];
  
  function convert(n) {
    if (n < 0) return "Minus " + convert(Math.abs(n));
    if (n < 12) return units[n];
    if (n < 20) return convert(n - 10) + " Belas";
    if (n < 100) return convert(Math.floor(n / 10)) + " Puluh " + convert(n % 10);
    if (n < 200) return "Seratus " + convert(n - 100);
    if (n < 1000) return convert(Math.floor(n / 100)) + " Ratus " + convert(n % 100);
    if (n < 2000) return "Seribu " + convert(n - 1000);
    if (n < 1000000) return convert(Math.floor(n / 1000)) + " Ribu " + convert(n % 1000);
    if (n < 1000000000) return convert(Math.floor(n / 1000000)) + " Juta " + convert(n % 1000000);
    if (n < 1000000000000) return convert(Math.floor(n / 1000000000)) + " Milyar " + convert(n % 1000000000);
    if (n < 1000000000000000) return convert(Math.floor(n / 1000000000000)) + " Triliun " + convert(n % 1000000000000);
    return "";
  }

  // Sanitasi input integer
  const val = Math.floor(Math.abs(nominal));
  if (val === 0) return "Nol Rupiah";
  
  // Format clean string
  let result = convert(val).replace(/\s+/g, ' ').trim();
  
  // Custom replacements for standard Indonesian formatting (e.g. "Satu Ratus" -> "Seratus", "Satu Ribu" -> "Seribu")
  // (Note: Already handled by < 200 and < 2000 conditions, but double check cleanup)
  result = result.replace("Satu Puluh", "Sepuluh");
  
  return result + " Rupiah";
}

// ----------------------------------------------------
// Formatter Helpers
// ----------------------------------------------------
function formatRupiah(amount, withPrefix = false) {
  const number = Number(amount) || 0;
  // Format value to 2 decimal places using Indonesian locale (id-ID)
  // Which uses period (.) as thousands separator and comma (,) as decimal separator
  const formatted = number.toLocaleString("id-ID", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
  return withPrefix ? `Rp ${formatted}` : formatted;
}

function formatKuantitas(amount) {
  const number = Number(amount) || 0;
  // Format with comma decimals, e.g. 65,10
  return number.toLocaleString("id-ID", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function formatDateIndo(dateStr) {
  if (!dateStr) return "";
  const parts = dateStr.split("-"); // YYYY-MM-DD
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}/${parts[1]}/${parts[0]}`; // DD/MM/YYYY
}

function getIndonesianDateText(dateStr) {
  if (!dateStr) return "";
  const parts = dateStr.split("-"); // YYYY-MM-DD
  if (parts.length !== 3) return "";
  const day = parseInt(parts[2]);
  const monthNames = [
    "JANUARI", "FEBRUARI", "MARET", "APRIL", "MEI", "JUNI",
    "JULI", "AGUSTUS", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DESEMBER"
  ];
  const month = monthNames[parseInt(parts[1]) - 1] || "";
  const year = parts[0];
  return `${day} ${month} ${year}`;
}

// ----------------------------------------------------
// Invoice List Management
// ----------------------------------------------------
function initApp() {
  const stored = localStorage.getItem("kwitansiku_invoices");
  if (stored) {
    try {
      invoices = JSON.parse(stored);
    } catch (e) {
      invoices = [...PREFILLED_DATA];
    }
  } else {
    invoices = [...PREFILLED_DATA];
    saveToStorage();
  }

  if (invoices.length > 0) {
    activeInvoiceId = invoices[0].id;
  }
  
  renderInvoiceList();
  loadActiveInvoice();
  setupSignaturePad();
  applyZoom();
}

function saveToStorage() {
  localStorage.setItem("kwitansiku_invoices", JSON.stringify(invoices));
}

function renderInvoiceList() {
  elInvoiceList.innerHTML = "";
  invoices.forEach(inv => {
    const li = document.createElement("li");
    li.className = "invoice-list-item";
    
    const activeClass = inv.id === activeInvoiceId ? "active" : "";
    
    // Calculate total price for preview subtitle
    const total = inv.items.reduce((acc, curr) => acc + (curr.quantity * curr.price), 0);
    
    li.innerHTML = `
      <div class="invoice-item-btn ${activeClass}" data-id="${inv.id}">
        <div class="invoice-item-title">${inv.ref || "Draft Invoice"}</div>
        <div class="invoice-item-meta">
          <span>${formatDateIndo(inv.date)}</span>
          <span style="font-weight: 700;">${formatRupiah(total, true)}</span>
        </div>
      </div>
      <button class="btn-delete-invoice-action" data-id="${inv.id}" title="Hapus Invoice">
        <svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2" fill="none"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
      </button>
    `;
    elInvoiceList.appendChild(li);
  });

  // Attach list click listeners
  document.querySelectorAll(".invoice-item-btn").forEach(btn => {
    btn.addEventListener("click", (e) => {
      activeInvoiceId = btn.getAttribute("data-id");
      document.querySelectorAll(".invoice-item-btn").forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      loadActiveInvoice();
    });
  });

  // Attach list delete listeners
  document.querySelectorAll(".btn-delete-invoice-action").forEach(btn => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = btn.getAttribute("data-id");
      if (confirm("Apakah Anda yakin ingin menghapus invoice ini?")) {
        deleteInvoice(id);
      }
    });
  });
}

function deleteInvoice(id) {
  invoices = invoices.filter(inv => inv.id !== id);
  if (activeInvoiceId === id) {
    activeInvoiceId = invoices.length > 0 ? invoices[0].id : "";
  }
  saveToStorage();
  renderInvoiceList();
  loadActiveInvoice();
}

