// ----------------------------------------------------
// Load Data Into Form & Live Preview
// ----------------------------------------------------
function loadActiveInvoice() {
  const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
  if (!activeInv) {
    clearFormAndPreview();
    return;
  }

  // Load to inputs
  elInvRef.value = activeInv.ref || "";
  elInvDate.value = activeInv.date || "";
  elInvDueDate.value = activeInv.dueDate || "";
  
  elCompanyName.value = activeInv.company?.name || "";
  elCompanyAddress.value = activeInv.company?.address || "";
  elCompanyPhone.value = activeInv.company?.phone || "";
  elCompanyEmail.value = activeInv.company?.email || "";
  
  elClientName.value = activeInv.client?.name || "";
  elClientAddress.value = activeInv.client?.address || "";
  elClientEmail.value = activeInv.client?.email || "";
  
  elInvNotes.value = activeInv.notes || "";
  elSignerName.value = activeInv.signerName || "";
  elSignerRole.value = activeInv.signerRole || "";

  // Reset logo file input filename representation and sync dropdown selection
  elCompanyLogoInput.value = "";
  if (activeInv.logo === "logo_ar_multi_karya.jpg" || activeInv.logo?.includes("ar multi karya")) {
    elCompanyLogoSelect.value = "ar_multi_karya";
    elCustomLogoUploadContainer.style.display = "none";
    elBtnRemoveLogo.style.display = "none";
  } else if (activeInv.logo === LOGO_KWT_SIDO_MAKMUR) {
    elCompanyLogoSelect.value = "kwt";
    elCustomLogoUploadContainer.style.display = "none";
    elBtnRemoveLogo.style.display = "none";
  } else if (activeInv.logo === LOGO_HAMDAN_TAHU_TEMPE) {
    elCompanyLogoSelect.value = "hamdan";
    elCustomLogoUploadContainer.style.display = "none";
    elBtnRemoveLogo.style.display = "none";
  } else if (!activeInv.logo) {
    elCompanyLogoSelect.value = "default";
    elCustomLogoUploadContainer.style.display = "none";
    elBtnRemoveLogo.style.display = "none";
  } else {
    elCompanyLogoSelect.value = "custom";
    elCustomLogoUploadContainer.style.display = "block";
    elBtnRemoveLogo.style.display = "inline-block";
  }

  // Sync stamp dropdown selection
  if (elCompanyStampInput) elCompanyStampInput.value = "";
  if (elCompanyStampSelect) {
    if (activeInv.stamp === "stempel_ar_multi_karya-removebg-preview.png" || activeInv.stamp?.includes("stempel_ar_multi_karya")) {
      elCompanyStampSelect.value = "ar_multi_karya";
      if (elCustomStampUploadContainer) elCustomStampUploadContainer.style.display = "none";
    } else if (!activeInv.stamp) {
      elCompanyStampSelect.value = "default";
      if (elCustomStampUploadContainer) elCustomStampUploadContainer.style.display = "none";
    } else {
      elCompanyStampSelect.value = "custom";
      if (elCustomStampUploadContainer) elCustomStampUploadContainer.style.display = "block";
    }
  }

  // Render items in editor grid
  renderEditorItems(activeInv.items);

  // Set signature drawing
  clearSigCanvas();
  if (activeInv.signature) {
    const img = new Image();
    img.onload = function() {
      ctxSig.drawImage(img, 0, 0, canvasSig.width, canvasSig.height);
    };
    img.src = activeInv.signature;
  }

  // Update Live Preview Sheet
  updatePreview();
}

