// ----------------------------------------------------
// Editor Table Render
// ----------------------------------------------------
function renderEditorItems(items) {
  elEditorItemsContainer.innerHTML = "";
  if (!items || items.length === 0) return;

  items.forEach((item, index) => {
    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td>
        <input type="text" class="edit-item-desc" data-index="${index}" value="${item.description || ""}" placeholder="Deskripsi barang">
      </td>
      <td>
        <input type="text" class="edit-item-unit" data-index="${index}" value="${item.qtyUnit || ""}" placeholder="Satuan">
      </td>
      <td>
        <input type="number" step="0.01" class="edit-item-qty" data-index="${index}" value="${item.quantity || 0}">
      </td>
      <td>
        <input type="number" step="100" class="edit-item-price" data-index="${index}" value="${item.price || 0}">
      </td>
      <td class="col-item-subtotal" style="vertical-align: middle; font-weight: 600; font-size: 0.85rem; padding-left: 0.5rem;">
        ${formatRupiah(item.quantity * item.price)}
      </td>
      <td>
        <button class="btn btn-danger btn-delete-item" data-index="${index}">
          <svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2.5" fill="none"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
        </button>
      </td>
    `;
    elEditorItemsContainer.appendChild(tr);
  });

  // Attach row event listeners
  document.querySelectorAll(".edit-item-desc").forEach(input => {
    input.addEventListener("input", (e) => {
      const idx = e.target.getAttribute("data-index");
      const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
      if (activeInv && activeInv.items[idx]) {
        activeInv.items[idx].description = e.target.value;
        saveToStorage();
        updatePreview();
      }
    });
  });

  document.querySelectorAll(".edit-item-unit").forEach(input => {
    input.addEventListener("input", (e) => {
      const idx = e.target.getAttribute("data-index");
      const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
      if (activeInv && activeInv.items[idx]) {
        activeInv.items[idx].qtyUnit = e.target.value;
        saveToStorage();
        updatePreview();
      }
    });
  });

  document.querySelectorAll(".edit-item-qty").forEach(input => {
    input.addEventListener("input", (e) => {
      const idx = e.target.getAttribute("data-index");
      const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
      if (activeInv && activeInv.items[idx]) {
        activeInv.items[idx].quantity = parseFloat(e.target.value) || 0;
        saveToStorage();
        
        // Update specific row total cell in editor instantly
        const rowSubtotal = activeInv.items[idx].quantity * activeInv.items[idx].price;
        e.target.closest("tr").querySelector(".col-item-subtotal").innerText = formatRupiah(rowSubtotal);
        
        updatePreview();
      }
    });
  });

  document.querySelectorAll(".edit-item-price").forEach(input => {
    input.addEventListener("input", (e) => {
      const idx = e.target.getAttribute("data-index");
      const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
      if (activeInv && activeInv.items[idx]) {
        activeInv.items[idx].price = parseFloat(e.target.value) || 0;
        saveToStorage();
        
        // Update specific row total cell in editor instantly
        const rowSubtotal = activeInv.items[idx].quantity * activeInv.items[idx].price;
        e.target.closest("tr").querySelector(".col-item-subtotal").innerText = formatRupiah(rowSubtotal);
        
        updatePreview();
      }
    });
  });

  document.querySelectorAll(".btn-delete-item").forEach(btn => {
    btn.addEventListener("click", (e) => {
      const idx = parseInt(btn.getAttribute("data-index"));
      const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
      if (activeInv) {
        activeInv.items.splice(idx, 1);
        saveToStorage();
        renderEditorItems(activeInv.items);
        updatePreview();
      }
    });
  });
}

function addItem() {
  const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
  if (!activeInv) return;

  const newItem = {
    id: "item-" + Date.now(),
    description: "ITEM BARU",
    qtyUnit: "PCS",
    quantity: 1,
    price: 0
  };

  activeInv.items.push(newItem);
  saveToStorage();
  renderEditorItems(activeInv.items);
  updatePreview();
}

// ----------------------------------------------------
// Preview Sheet Sync & Math
// ----------------------------------------------------
function updatePreview() {
  const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
  if (!activeInv) return;

  // Metadata
  elViewRef.innerText = activeInv.ref || "-";
  elViewDate.innerText = formatDateIndo(activeInv.date);
  elViewDueDate.innerText = formatDateIndo(activeInv.dueDate);

  // Logo Preview Toggle
  if (activeInv.logo) {
    elViewLogoImg.src = activeInv.logo;
    elViewLogoImg.style.display = "block";
    elViewLogoBox.style.display = "flex";
    elBtnRemoveLogo.style.display = "inline-block";
  } else {
    elViewLogoImg.src = "";
    elViewLogoImg.style.display = "none";
    elViewLogoBox.style.display = "none";
    elBtnRemoveLogo.style.display = "none";
  }

  // Address
  elViewCompanyName.innerText = activeInv.company?.name || "";
  elViewCompanyAddress.innerText = activeInv.company?.address || "";
  elViewCompanyPhone.innerText = activeInv.company?.phone || "";
  elViewCompanyEmail.innerText = activeInv.company?.email || "";

  elViewClientName.innerText = activeInv.client?.name || "";
  elViewClientAddress.innerText = activeInv.client?.address || "";
  elViewClientEmail.innerText = activeInv.client?.email || "";

  // Notes
  elViewNotes.innerText = activeInv.notes || "";

  // Items Render
  elViewItemsContainer.innerHTML = "";
  let subtotal = 0;
  
  activeInv.items.forEach(item => {
    const itemTotal = item.quantity * item.price;
    subtotal += itemTotal;

    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td class="col-urai">${item.description || ""}</td>
      <td class="col-qty">${item.qtyUnit || ""}</td>
      <td class="col-kuan">${formatKuantitas(item.quantity)}</td>
      <td class="col-harga">${formatRupiah(item.price)}</td>
      <td class="col-jumlah">${formatRupiah(itemTotal)}</td>
    `;
    elViewItemsContainer.appendChild(tr);
  });

  // Calculate Subtotal & Total (directly equal in this template)
  const total = subtotal;

  elViewSubtotal.innerText = formatRupiah(subtotal, true);
  elViewTotal.innerText = formatRupiah(total, true);

  // Indonesian Terbilang Text
  elViewTerbilang.innerText = angkaKeTerbilang(total);

  // Signer Details & Title
  if (elViewSigTitle) {
    if (activeInv.company?.name === "PT AR MULTI KARYA") {
      elViewSigTitle.innerText = "DIREKTUR";
    } else {
      elViewSigTitle.innerText = "SUPPLIER";
    }
  }
  elViewSignerName.innerText = activeInv.signerName || "AHMAD ROFIQ";
  elViewSignerRole.innerText = activeInv.signerRole || "PT. AR MULTI KARYA";

  // Signature & Stamp rendering
  if (activeInv.signature) {
    elViewSigImg.src = activeInv.signature;
    elViewSigImg.style.display = "block";
    elViewSigPlaceholder.style.display = "none";
  } else {
    elViewSigImg.style.display = "none";
    elViewSigPlaceholder.style.display = "block";
  }

  if (elViewStampImg) {
    if (activeInv.stamp) {
      elViewStampImg.src = activeInv.stamp;
      elViewStampImg.style.display = "block";
    } else {
      elViewStampImg.src = "";
      elViewStampImg.style.display = "none";
    }
  }

  // Update current list metadata display without complete list redraw
  const activeListItem = document.querySelector(`.invoice-item-btn[data-id="${activeInvoiceId}"]`);
  if (activeListItem) {
    activeListItem.querySelector(".invoice-item-title").innerText = activeInv.ref || "Draft Invoice";
    activeListItem.querySelector(".invoice-item-meta span:first-child").innerText = formatDateIndo(activeInv.date);
    activeListItem.querySelector(".invoice-item-meta span:last-child").innerText = formatRupiah(total, true);
  }
}

