// ----------------------------------------------------
// Signature Pad Controller
// ----------------------------------------------------
function setupSignaturePad() {
  // Clear pad canvas on click
  elBtnClearSig.addEventListener("click", () => {
    clearSigCanvas();
    const current = invoices.find(inv => inv.id === activeInvoiceId);
    if (current) {
      current.signature = null;
      saveToStorage();
      updatePreview();
    }
  });

  // Line drawing styles
  ctxSig.strokeStyle = "#ffffff"; // White ink for dark canvas draw area
  ctxSig.lineWidth = 2.5;
  ctxSig.lineCap = "round";
  ctxSig.lineJoin = "round";

  // Position getter helper
  function getMousePos(canvasDom, touchOrMouseEvent) {
    const rect = canvasDom.getBoundingClientRect();
    const clientX = touchOrMouseEvent.touches ? touchOrMouseEvent.touches[0].clientX : touchOrMouseEvent.clientX;
    const clientY = touchOrMouseEvent.touches ? touchOrMouseEvent.touches[0].clientY : touchOrMouseEvent.clientY;
    
    // Account for CSS scale
    return {
      x: (clientX - rect.left) * (canvasDom.width / rect.width),
      y: (clientY - rect.top) * (canvasDom.height / rect.height)
    };
  }

  // Draw handlers
  function startDrawing(e) {
    isDrawing = true;
    sigChanged = true;
    const pos = getMousePos(canvasSig, e);
    ctxSig.beginPath();
    ctxSig.moveTo(pos.x, pos.y);
    e.preventDefault();
  }

  function draw(e) {
    if (!isDrawing) return;
    const pos = getMousePos(canvasSig, e);
    ctxSig.lineTo(pos.x, pos.y);
    ctxSig.stroke();
    e.preventDefault();
  }

  function stopDrawing() {
    if (!isDrawing) return;
    isDrawing = false;
    
    if (sigChanged) {
      // Create a transparent signature PNG with Dark Blue/Black color
      // Since printing signature must be dark on white paper, convert white strokes to black/blue ink!
      const finalSig = generateInvoiceSignature();
      const current = invoices.find(inv => inv.id === activeInvoiceId);
      if (current) {
        current.signature = finalSig;
        saveToStorage();
        updatePreview();
      }
    }
  }

  // Mouse Listeners
  canvasSig.addEventListener("mousedown", startDrawing);
  canvasSig.addEventListener("mousemove", draw);
  window.addEventListener("mouseup", stopDrawing);

  // Touch Listeners
  canvasSig.addEventListener("touchstart", startDrawing, { passive: false });
  canvasSig.addEventListener("touchmove", draw, { passive: false });
  canvasSig.addEventListener("touchend", stopDrawing);
}

function clearSigCanvas() {
  ctxSig.clearRect(0, 0, canvasSig.width, canvasSig.height);
  sigChanged = false;
}

// Convert drawn stroke to standard dark-blue printed ink format
function generateInvoiceSignature() {
  // Create a temporary canvas
  const tempCanvas = document.createElement("canvas");
  tempCanvas.width = canvasSig.width;
  tempCanvas.height = canvasSig.height;
  const tempCtx = tempCanvas.getContext("2d");

  // Fetch strokes data from main canvas and copy it to temporary, converting white lines to blue-ink lines
  const imgData = ctxSig.getImageData(0, 0, canvasSig.width, canvasSig.height);
  const data = imgData.data;

  // Read white pixel values drawn and write clean blue/black pixel strokes to temp canvas
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i+1];
    const b = data[i+2];
    const alpha = data[i+3];

    // If it's a drawn stroke pixel (white: r=255,g=255,b=255)
    if (r > 150 && g > 150 && b > 150 && alpha > 0) {
      // Color it Dark Steel Blue (#2F5597 / RGB: 47, 85, 151)
      data[i] = 47;
      data[i+1] = 85;
      data[i+2] = 151;
    }
  }
  tempCtx.putImageData(imgData, 0, 0);
  return tempCanvas.toDataURL("image/png");
}

// ----------------------------------------------------
// Preview Pane Scaling Controller (Zoom)
// ----------------------------------------------------
function applyZoom() {
  elInvoiceSheet.style.transform = `scale(${zoomLevel})`;
  elZoomValue.innerText = `${Math.round(zoomLevel * 100)}%`;
  
  // Dynamic page height correction margin
  const scaledHeight = elInvoiceSheet.getBoundingClientRect().height;
  const container = elInvoiceSheet.parentElement;
  
  // Set placeholder dimensions so footer spacing isn't collapsed in container overflow
  if (zoomLevel < 1) {
    container.style.minHeight = `${scaledHeight + 40}px`;
  } else {
    container.style.minHeight = "auto";
  }
}

elBtnZoomIn.addEventListener("click", () => {
  if (zoomLevel < 1.5) {
    zoomLevel += 0.05;
    applyZoom();
  }
});

elBtnZoomOut.addEventListener("click", () => {
  if (zoomLevel > 0.4) {
    zoomLevel -= 0.05;
    applyZoom();
  }
});

