elBtnDownloadJpg.addEventListener("click", () => {
  const activeInv = invoices.find(inv => inv.id === activeInvoiceId);
  const refName = activeInv ? (activeInv.ref ? activeInv.ref.replace(/[\/\\?%*:|"<>]/g, "-") : "Draft") : "Invoice";
  const fileName = `Invoice_${refName}.jpg`;

  const originalText = elBtnDownloadJpg.innerHTML;
  elBtnDownloadJpg.innerHTML = "Processing...";
  elBtnDownloadJpg.disabled = true;

  html2canvas(elInvoiceSheet, {
    scale: 2.5, // Crisp high-res rendering
    useCORS: true,
    allowTaint: true,
    logging: false,
    backgroundColor: "#ffffff",
    onclone: (clonedDoc) => {
      const clonedSheet = clonedDoc.getElementById("invoice-sheet-print");
      if (clonedSheet) {
        clonedSheet.style.transform = "none";
        clonedSheet.style.margin = "0";
        clonedSheet.style.boxShadow = "none";
      }
    }
  }).then(canvas => {
    const imgData = canvas.toDataURL("image/jpeg", 0.95);
    const link = document.createElement("a");
    link.href = imgData;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    elBtnDownloadJpg.innerHTML = originalText;
    elBtnDownloadJpg.disabled = false;
  }).catch(err => {
    console.error("Error generating JPG:", err);
    alert("Gagal mengunduh JPG: " + err.message);
    elBtnDownloadJpg.innerHTML = originalText;
    elBtnDownloadJpg.disabled = false;
  });
});

// Import/Export Backup Handler
elBtnExport.addEventListener("click", () => {
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(invoices, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", `Backup_Invoice_Hamdan_${new Date().toISOString().slice(0,10)}.json`);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
});

elBtnImport.addEventListener("click", () => {
  elInputImport.click();
});

elInputImport.addEventListener("change", (e) => {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(evt) {
    try {
      const parsed = JSON.parse(evt.target.result);
      if (Array.isArray(parsed) && parsed.length > 0 && parsed[0].id) {
        invoices = parsed;
        activeInvoiceId = invoices[0].id;
        saveToStorage();
        renderInvoiceList();
        loadActiveInvoice();
        alert("Data Backup Invoice berhasil di-import!");
      } else {
        alert("Format Backup Data tidak valid!");
      }
    } catch (err) {
      alert("Gagal membaca file JSON!");
    }
  };
  reader.readAsText(file);
});

// Run
initApp();
bindFormFields();
